  "pkg/dev-extension/pages/DevHome.vue": "<script>\nexport default {\n  name: 'DevHome',\n\n  data() {\n    return {\n      // Edit this string and it should change in the running Rancher without a reload.\n      headline: 'DevExtension is live',\n      loadedAt: new Date().toLocaleTimeString()\n    };\n  }\n};\n</script>\n\n<template>\n  <div class=\"dev-home\">\n    <h1>{{ headline }}</h1>\n    <p class=\"subtitle\">\n      This page is served by the DevExtension dev server, through the k8s proxy,\n      into the Rancher instance you are looking at.\n    </p>\n    <div class=\"marker\">\n      component first rendered at {{ loadedAt }}\n    </div>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .dev-home {\n    padding: 20px;\n\n    h1 {\n      color: var(--primary);\n    }\n\n    .subtitle {\n      max-width: 60ch;\n      margin-bottom: 20px;\n    }\n\n    .marker {\n      display: inline-block;\n      padding: 8px 12px;\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      font-family: monospace;\n    }\n  }\n</style>\n",
  "pkg/dev-extension/pages/Floof.vue": "<script>\nimport Loading from '@shell/components/Loading';\nimport ResourceTable from '@shell/components/ResourceTable';\nimport { CONFIG_MAP } from '@shell/config/types';\n\n/**\n * An extension page inside Rancher's own Cluster Explorer.\n *\n * Two things make it a real explorer page rather than a page that merely looks like one:\n * the route is registered under the explorer's `c-cluster-` parent so the cluster nav and\n * switcher stay in place, and the rows come from the Steve `cluster` store, so ResourceTable\n * gets the same schema-driven columns, sorting, grouping and live updates it gives any\n * built-in list.\n */\nexport default {\n  // Two words to satisfy vue/multi-word-component-names, which exists so a component can\n  // never collide with a current or future HTML element. The page is still \"Floof\".\n  name: 'FloofPage',\n\n  components: { Loading, ResourceTable },\n\n  async fetch() {\n    // The schema comes back with the resource, and ResourceTable needs it to build columns -\n    // without it the table renders but has nothing to put in the header row.\n    this.rows = await this.$store.dispatch('cluster/findAll', { type: CONFIG_MAP });\n  },\n\n  data() {\n    return { rows: [] };\n  },\n\n  computed: {\n    schema() {\n      return this.$store.getters['cluster/schemaFor'](CONFIG_MAP);\n    }\n  }\n};\n</script>\n\n<template>\n  <Loading v-if=\"$fetchState.pending\" />\n  <div\n    v-else\n    class=\"floof\"\n  >\n    <header>\n      <h1>Floof</h1>\n      <p class=\"subheader\">\n        doof\n      </p>\n    </header>\n\n    <ResourceTable\n      :schema=\"schema\"\n      :rows=\"rows\"\n      :headers=\"schema ? null : []\"\n    />\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .floof {\n    header {\n      // The shell styles `header` as a flex row (it is the masthead pattern on every list\n      // page), which puts the subheader out to the right of the title instead of under it.\n      // Overridden rather than renamed so the element stays semantically the page header.\n      display:        block;\n      margin-bottom:  20px;\n\n      h1 {\n        margin-bottom: 0;\n      }\n\n      .subheader {\n        margin:  0;\n        opacity: 0.7;\n      }\n    }\n  }\n</style>\n",
  "pkg/dev-extension/product.ts": "import { IPlugin } from '@shell/core/types';\nimport {\n  PRODUCT_NAME, CUSTOM_PAGE_NAME, BLANK_CLUSTER, HOME_ROUTE,\n  EXPLORER_PRODUCT, FLOOF_PAGE, FLOOF_ROUTE\n} from './config/constants';\n\n// `store` is the raw Vuex store the extension manager hands to every product init, and\n// $plugin.DSL takes it as `any`. There is no narrower type to reach for.\n// eslint-disable-next-line @typescript-eslint/no-explicit-any\nexport function init($plugin: IPlugin, store: any) {\n  const { product, basicType, virtualType } = $plugin.DSL(store, PRODUCT_NAME);\n\n  // `public` is what makes the product visible without a session, and the shell honours it at\n  // runtime, but TypeMapProduct does not declare it. The dev build only warns; the production\n  // build that `hmr: off` mode needs treats it as an error, so the literal is widened here.\n  const productOpts: Record<string, unknown> = {\n    icon:                'flask',\n    public:              true,\n    inStore:             'management',\n    weight:              100,\n    showClusterSwitcher: false,\n    to:                  {\n      name:   HOME_ROUTE,\n      params: { product: PRODUCT_NAME, cluster: BLANK_CLUSTER }\n    }\n  };\n\n  product(productOpts);\n\n  virtualType({\n    name:  CUSTOM_PAGE_NAME,\n    label: 'Live Reload Demo',\n    route: {\n      name:   HOME_ROUTE,\n      params: { product: PRODUCT_NAME, cluster: BLANK_CLUSTER }\n    },\n    weight: 100\n  });\n\n  basicType([CUSTOM_PAGE_NAME]);\n\n  // Floof goes into Rancher's Cluster Explorer, not into this product.\n  //\n  // A second DSL() call scoped to 'explorer' is how an extension adds to a product it does\n  // not own - the same virtualType/basicType calls, aimed at someone else's nav. `group:\n  // 'Root'` puts it at the top level alongside Cluster and Workloads rather than inside a\n  // resource group, matching how the shell registers its own non-resource pages.\n  const explorer = $plugin.DSL(store, EXPLORER_PRODUCT);\n\n  explorer.virtualType({\n    name:       FLOOF_PAGE,\n    label:      'Floof',\n    group:      'Root',\n    icon:       'folder',\n    namespaced: false,\n    weight:     99,\n    route:      { name: FLOOF_ROUTE },\n    exact:      true\n  });\n\n  explorer.basicType([FLOOF_PAGE], 'Root');\n}\n",
  "pkg/dev-extension/routing/index.ts": "import { RouteRecordRaw } from 'vue-router';\nimport { PluginRouteRecordRaw } from '@shell/core/types';\nimport {\n  PRODUCT_NAME, CUSTOM_PAGE_NAME, BLANK_CLUSTER, HOME_ROUTE,\n  EXPLORER_PRODUCT, FLOOF_PAGE, FLOOF_ROUTE\n} from '../config/constants';\nimport DevHome from '../pages/DevHome.vue';\nimport Floof from '../pages/Floof.vue';\n\n/**\n * This extension's own product page. Top-level products need the `/{product}/c/:cluster/`\n * shape and the BLANK_CLUSTER param, since they have no cluster of their own.\n */\nconst ownRoutes: RouteRecordRaw[] = [\n  {\n    name:      HOME_ROUTE,\n    path:      `/${ PRODUCT_NAME }/c/:cluster/${ CUSTOM_PAGE_NAME }`,\n    component: DevHome,\n    meta:      {\n      product: PRODUCT_NAME,\n      cluster: BLANK_CLUSTER\n    }\n  }\n];\n\n/**\n * Floof, which belongs to Rancher's Cluster Explorer rather than to this extension.\n *\n * `parent: 'default'` is what makes it an explorer page rather than a bare page at an\n * explorer-shaped URL. The shell's own cluster pages are children of the `default` template\n * route (shell/config/router/routes.js), which is what supplies the side nav, the cluster\n * switcher and the header. Registered at the top level instead, the component renders alone\n * on a blank page - the usual symptom of getting this wrong.\n *\n * `meta.product` is equally load-bearing: it tells the shell which product's nav to show and\n * which entry to highlight. Without it the page renders inside the explorer but the nav does\n * not know Floof is the current page.\n */\nconst explorerRoutes: PluginRouteRecordRaw[] = [\n  {\n    parent: 'default',\n    route:  {\n      name:      FLOOF_ROUTE,\n      path:      `/c/:cluster/${ EXPLORER_PRODUCT }/${ FLOOF_PAGE }`,\n      component: Floof,\n      meta:      { product: EXPLORER_PRODUCT }\n    }\n  }\n];\n\nexport default [...ownRoutes, ...explorerRoutes];\n",
